import { esc, icon, badge, avatar, progress, empty, fmt, money } from './ui.js';
import { handleOrganization } from './organization.js';

let goalFilter = 'all';
let decisionFilter = 'pending';
let gapFilter = 'all';
let policyFilter = 'all';
const statusNames = {'on-track':'En bonne voie','at-risk':'À surveiller','off-track':'En retard'};
const statusTones = {'on-track':'green','at-risk':'amber','off-track':'red'};
const categories = {capacity:'Capacité',capability:'Compétence',authority:'Autorité',data:'Données',adoption:'Adoption'};
const modes = {block:'Bloquer',ask:'Faire valider',log:'Journaliser'};
const types = {approval:'Validation',exception:'Exception',budget:'Budget'};
const teams = ['Opérations','Investissement','Conformité','Distribution'];
const id = prefix => `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,6)}`;
const date = value => { const d = new Date(value); return Number.isNaN(d.getTime()) ? esc(value || '—') : d.toLocaleDateString('fr-FR',{day:'numeric',month:'short'}); };
const ownerInitials = name => String(name || 'MK').split(' ').map(x=>x[0]).slice(0,2).join('');
const ownerAvatar = name => avatar({name,initials:ownerInitials(name),type:'human'});
const opts = (values, selected) => values.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v)}</option>`).join('');
const head = (eyebrow,title,description,action='') => `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${title}</h1><p class="page-description">${description}</p></div><div class="head-actions">${action}</div></div>`;
const filterBtn = (label,value,current,action,count='') => `<button class="filter-btn ${value===current?'active':''}" data-action="${action}" data-value="${value}" aria-pressed="${value===current}">${label}${count!==''?` <span class="filter-count">${count}</span>`:''}</button>`;
const evidence = items => `<ul class="evidence">${(items||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
const goalStatus = goal => badge(statusNames[goal.status] || 'À surveiller',statusTones[goal.status] || 'amber');
const goalPercent = goal => Math.min(100,Math.max(0,Number(goal.progress)||0));

const scenarioElapsed=35, scenarioQuarter=92;
export function goalMetrics(g){const krs=(g.krs||[]).map(k=>{const baseline=Number(k.baseline??0),current=Number(k.current),target=Number(k.target),delta=target-baseline,ratio=delta?(current-baseline)/delta:(current===target?1:0),projected=baseline+(current-baseline)*scenarioQuarter/scenarioElapsed;return {...k,baseline,current,target,projected:k.unit==='%'?Math.max(0,Math.min(100,projected)):projected,progress:Math.max(0,Math.min(100,ratio*100))};});return {krs,progress:krs.length?Math.round(krs.reduce((a,k)=>a+k.progress,0)/krs.length):0};}
function miniTrend(k){const values=k.series?.length?k.series:[k.baseline,k.current],lo=Math.min(...values,k.target),hi=Math.max(...values,k.target),range=hi-lo||1,point=(v,i)=>`${12+i*(276/(values.length-1||1))},${54-(v-lo)/range*42}`,poly=values.map(point).join(' '),targetY=54-(k.target-lo)/range*42;return `<svg class="gp-goal-chart" viewBox="0 0 300 64" role="img" aria-label="Trajectoire illustrative : de ${esc(k.baseline)} à ${esc(k.current)}, cible ${esc(k.target)}"><line x1="12" y1="${targetY}" x2="288" y2="${targetY}" stroke="#d7c6e9" stroke-dasharray="4 4"/><polyline points="${poly}" fill="none" stroke="#9c78c9" stroke-width="2"/>${values.map((v,i)=>`<circle cx="${12+i*276/(values.length-1||1)}" cy="${54-(v-lo)/range*42}" r="2.5" fill="#9c78c9"/>`).join('')}</svg>`;}
export function renderGoals(s) {
 const filtered=s.goals.filter(g=>goalFilter==='all'||g.status===goalFilter),onTrack=s.goals.filter(g=>g.status==='on-track').length;
 return `${head('CAP COMMUN','Des objectifs qui se répondent.','De l’ambition de l’organisation aux résultats de chaque équipe, avec une source derrière chaque mesure.',`<button class="btn btn-primary" data-action="gov-new-goal">${icon('plus',16)} Nouvel objectif</button>`)}<div class="notice goal-notice">${icon('target',21)}<div><strong>${onTrack} objectif${onTrack>1?'s':''} sur ${s.goals.length} en bonne voie.</strong> <span class="muted">Les tendances et projections sont illustratives, à partir du scénario au 4 novembre 2026.</span></div></div><div class="filter-bar">${filterBtn('Tous les objectifs','all',goalFilter,'gov-goal-filter',s.goals.length)}${filterBtn('En bonne voie','on-track',goalFilter,'gov-goal-filter',onTrack)}${filterBtn('À surveiller','at-risk',goalFilter,'gov-goal-filter')}${filterBtn('En retard','off-track',goalFilter,'gov-goal-filter')}</div><div class="grid-2 goals-grid">${filtered.map(g=>{const m=goalMetrics(g),parent=s.goals.find(x=>x.id===g.parentId),children=s.goals.filter(x=>x.parentId===g.id);return `<article class="card goal-card"><div class="goal-top"><span class="eyebrow">${esc(g.team)}</span>${goalStatus(g)}</div>${parent?`<div class="gp-goal-hierarchy">${icon('target',12)}<button data-action="gov-goal-detail" data-id="${esc(parent.id)}">Contribue à ${esc(parent.title)}</button></div>`:''}<button class="goal-title-button" data-action="gov-goal-detail" data-id="${esc(g.id)}"><h2 class="card-title">${esc(g.title)}</h2>${icon('arrow',18)}</button><p class="muted small">${esc(g.description)}</p><div class="goal-progress-label"><span>Progression des résultats clés</span><strong>${m.progress}<small>%</small></strong></div>${progress(m.progress,g.status==='off-track'?'red':g.status==='on-track'?'green':'purple')}<div class="kr-list">${m.krs.slice(0,3).map(k=>`<div class="kr-row"><span>${esc(k.label)}</span><strong>${fmt(k.current)} ${esc(k.unit||'')} <span class="muted">/ ${fmt(k.target)}</span></strong></div>`).join('')}</div>${children.length?`<p class="small muted">${children.length} objectif${children.length>1?'s':''} d’équipe rattaché${children.length>1?'s':''}</p>`:''}<div class="goal-footer"><div class="person">${ownerAvatar(g.owner)}<span class="small">${esc(g.owner)}</span></div><span class="muted small">${icon('clock',14)} ${date(g.targetDate)}</span></div></article>`;}).join('')||empty('Aucun objectif dans cette vue','Essayez un autre statut.')}</div>`;
}
function goalDrawer(g,s,ctx){const linked=s.processes.filter(p=>(g.processIds||[]).includes(p.id)||p.goalId===g.id),m=goalMetrics(g),children=s.goals.filter(x=>x.parentId===g.id),parent=s.goals.find(x=>x.id===g.parentId);ctx.drawer({title:g.title,subtitle:`${g.team} · ${g.owner}`,body:`<div class="row between">${goalStatus(g)}<span class="muted small">Échéance ${date(g.targetDate)}</span></div>${parent?`<p class="gp-goal-hierarchy">Contribue à <button data-action="gov-goal-detail" data-id="${esc(parent.id)}">${esc(parent.title)}</button></p>`:''}<p class="detail-lead">${esc(g.description)}</p><div class="goal-progress-label"><span>Progression mesurée depuis la référence</span><strong>${m.progress} %</strong></div>${progress(m.progress)}<h3 class="section-title">Résultats clés</h3>${m.krs.map(k=>`<article class="gp-kr-row"><div class="gp-kr-title"><strong>${esc(k.label)}</strong>${badge(k.progress>=100?'Cible atteinte':'En cours',k.progress>=100?'green':'purple')}</div><div class="gp-kr-metrics"><div><small>Référence</small><strong>${fmt(k.baseline)} ${esc(k.unit||'')}</strong></div><div><small>Actuel</small><strong>${fmt(k.current)} ${esc(k.unit||'')}</strong></div><div><small>Cible</small><strong>${fmt(k.target)} ${esc(k.unit||'')}</strong></div><div><small>Projection illustrative</small><strong>${fmt(k.projected)} ${esc(k.unit||'')}</strong></div></div>${miniTrend(k)}<p class="form-help">Extrapolation linéaire du scénario : 35 jours observés sur un trimestre de 92 jours. Cette estimation n’est pas une prévision validée.</p><div class="gp-kr-evidence">${icon('info',13)} ${esc(k.source||'Source non renseignée')}${k.evidence?`<p>${esc(k.evidence)}</p>`:''}</div><div class="gp-kr-actions"><button class="btn btn-ghost btn-sm" data-action="gov-edit-kr" data-id="${esc(g.id)}" data-kr="${esc(k.id)}">Modifier</button><button class="btn btn-ghost btn-sm" data-action="gov-delete-kr" data-id="${esc(g.id)}" data-kr="${esc(k.id)}">Retirer</button></div></article>`).join('')}<button class="btn btn-sm" data-action="gov-add-kr" data-id="${esc(g.id)}">${icon('plus',14)} Ajouter un résultat clé</button><h3 class="section-title">Objectifs d’équipe</h3>${children.map(c=>`<div class="gp-child-goal"><button class="text-link" data-action="gov-goal-detail" data-id="${esc(c.id)}">${esc(c.title)}</button><p class="muted small">${esc(c.owner)} · ${goalMetrics(c).progress} %</p></div>`).join('')||'<p class="muted small">Aucun objectif d’équipe rattaché.</p>'}<button class="btn btn-ghost btn-sm" data-action="gov-new-subgoal" data-id="${esc(g.id)}">${icon('plus',14)} Décliner pour une équipe</button><h3 class="section-title">Processus contributeurs</h3>${linked.map(p=>`<button class="linked-row" data-action="wf-open" data-id="${esc(p.id)}">${icon('workflow',18)}<span>${esc(p.name)}</span>${icon('arrow',16)}</button>`).join('')||'<p class="muted small">Aucun processus associé.</p>'}<div class="drawer-actionbar"><button class="btn btn-primary" data-action="gov-edit-goal" data-id="${esc(g.id)}">${icon('edit',16)} Modifier l’objectif</button></div>`});}
export function validGoalParent(goals,goalId,parentId){if(!parentId)return true;let parent=goals.find(g=>g.id===parentId);const seen=new Set([goalId]);while(parent){if(seen.has(parent.id))return false;seen.add(parent.id);parent=goals.find(g=>g.id===parent.parentId);}return true;}
function goalForm(g,s,ctx,parentId=''){const isNew=!g,initial=g||{title:'',description:'',owner:'Matthieu Keip',team:'Opérations',targetDate:'2026-12-31',progress:0,status:'on-track',parentId,krs:[],processIds:[]};ctx.closeDrawer();ctx.modal({title:isNew?'Définir un objectif':'Modifier l’objectif',subtitle:'Un résultat mesurable, un responsable et sa contribution à un cap commun.',submitLabel:isNew?'Créer l’objectif':'Enregistrer',body:`<div class="field"><label for="goal-title">Objectif</label><input id="goal-title" name="title" value="${esc(initial.title)}" required maxlength="160"></div><div class="field"><label for="goal-description">Résultat attendu</label><textarea id="goal-description" name="description" rows="3" required maxlength="700">${esc(initial.description)}</textarea></div><div class="form-grid"><div class="field"><label for="goal-owner">Responsable humain</label><select id="goal-owner" name="owner">${opts([...new Set(s.agents.filter(a=>a.type==='human').map(a=>a.name))],initial.owner)}</select></div><div class="field"><label for="goal-team">Équipe</label><select id="goal-team" name="team">${opts([...new Set(s.agents.map(a=>a.team))],initial.team)}</select></div><div class="field"><label for="goal-date">Échéance</label><input id="goal-date" name="targetDate" type="date" value="${esc(initial.targetDate?.slice(0,10))}" required></div><div class="field"><label for="goal-status">Appréciation du responsable</label><select id="goal-status" name="status">${Object.entries(statusNames).map(([k,v])=>`<option value="${k}" ${k===initial.status?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="field"><label for="goal-parent">Contribue à l’objectif</label><select id="goal-parent" name="parentId"><option value="">Objectif de l’organisation</option>${s.goals.filter(x=>x.id!==g?.id).map(x=>`<option value="${esc(x.id)}" ${x.id===initial.parentId?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div>${isNew?`<h3 class="section-title">Premier résultat clé</h3><div class="field"><label for="goal-kr-label">Indicateur</label><input id="goal-kr-label" name="krLabel" required maxlength="140" placeholder="Ex. Dossiers acceptés dans le délai"></div><div class="form-grid"><div class="field"><label for="goal-kr-baseline">Référence</label><input id="goal-kr-baseline" name="baseline" type="number" step="any" value="0" required></div><div class="field"><label for="goal-kr-target">Cible</label><input id="goal-kr-target" name="target" type="number" step="any" value="100" required></div><div class="field"><label for="goal-kr-unit">Unité</label><input id="goal-kr-unit" name="unit" value="%" maxlength="16"></div></div>`:''}<h3 class="section-title">Processus associés</h3>${s.processes.map(p=>`<label class="gp-process-pick"><input type="checkbox" name="processIds" value="${esc(p.id)}" ${(initial.processIds||[]).includes(p.id)?'checked':''}><span>${esc(p.name)}</span></label>`).join('')}`,onSubmit:fd=>{const title=String(fd.get('title')||'').trim(),parent=String(fd.get('parentId')||''),goalId=g?.id||id('goal');if(!title)return false;if(!validGoalParent(ctx.getState().goals,goalId,parent)){ctx.toast('Ce rattachement créerait une boucle entre objectifs.');return false;}const processIds=fd.getAll('processIds').map(String),record={...initial,id:goalId,title,description:String(fd.get('description')||'').trim(),owner:String(fd.get('owner')),team:String(fd.get('team')),targetDate:String(fd.get('targetDate')),status:String(fd.get('status')),parentId:parent||null,processIds};if(isNew){const baseline=Number(fd.get('baseline')),target=Number(fd.get('target'));if(!Number.isFinite(baseline)||!Number.isFinite(target)||target===baseline){ctx.toast('La cible doit être différente de la référence.');return false;}record.krs=[{id:id('kr'),label:String(fd.get('krLabel')||'').trim(),baseline,current:baseline,target,unit:String(fd.get('unit')||''),source:'À documenter',series:[baseline,baseline]}];}record.progress=goalMetrics(record).progress;ctx.update(st=>{if(isNew)st.goals.unshift(record);else Object.assign(st.goals.find(x=>x.id===goalId),record);st.processes.forEach(p=>{const links=new Set(p.goalIds||[p.goalId].filter(Boolean));if(processIds.includes(p.id))links.add(goalId);else links.delete(goalId);p.goalIds=[...links];if(!p.goalId&&processIds.includes(p.id))p.goalId=goalId;if(p.goalId===goalId&&!processIds.includes(p.id))p.goalId=p.goalIds[0]||'';});},isNew?'Objectif créé':'Objectif modifié',title);ctx.toast('L’objectif est enregistré.');}});}
function krForm(g,k,ctx){const initial=k||{id:id('kr'),label:'',baseline:0,current:0,target:100,unit:'%',source:'',evidence:''};ctx.closeDrawer();ctx.modal({title:k?'Actualiser le résultat clé':'Ajouter un résultat clé',subtitle:g.title,body:`<div class="field"><label for="kr-label">Indicateur</label><input id="kr-label" name="label" value="${esc(initial.label)}" required maxlength="140"></div><div class="form-grid">${[['baseline','Référence'],['current','Valeur actuelle'],['target','Cible']].map(([key,label])=>`<div class="field"><label for="kr-${key}">${label}</label><input id="kr-${key}" name="${key}" type="number" step="any" value="${Number(initial[key])}" required></div>`).join('')}<div class="field"><label for="kr-unit">Unité</label><input id="kr-unit" name="unit" value="${esc(initial.unit||'')}" maxlength="16"></div></div><div class="field"><label for="kr-source">Source de la mesure</label><input id="kr-source" name="source" value="${esc(initial.source||'')}" required maxlength="180"></div><div class="field"><label for="kr-evidence">Justificatif</label><textarea id="kr-evidence" name="evidence" rows="3" maxlength="1000">${esc(initial.evidence||'')}</textarea></div>`,onSubmit:fd=>{const baseline=Number(fd.get('baseline')),current=Number(fd.get('current')),target=Number(fd.get('target')),label=String(fd.get('label')||'').trim();if(!label||![baseline,current,target].every(Number.isFinite)||baseline===target){ctx.toast('Renseignez un indicateur et une cible différente de la référence.');return false;}const record={...initial,label,baseline,current,target,unit:String(fd.get('unit')||''),source:String(fd.get('source')||'').trim(),evidence:String(fd.get('evidence')||'').trim(),series:[baseline,...[.25,.5,.75].map(r=>baseline+(current-baseline)*r),current]};ctx.update(st=>{const goal=st.goals.find(x=>x.id===g.id);if(k)Object.assign(goal.krs.find(x=>x.id===k.id),record);else goal.krs.push(record);goal.progress=goalMetrics(goal).progress;},k?'Mesure de résultat actualisée':'Résultat clé ajouté',`${g.title} · ${label}`);ctx.toast('Le résultat clé est enregistré.');}});}

export function renderDecisions(s) {
 const pending=s.decisions.filter(d=>d.status==='pending');
 const filtered=s.decisions.filter(d=>decisionFilter==='all'||(decisionFilter==='handled'?d.status!=='pending':d.status==='pending'));
 return `${head('VOTRE FILE DE DÉCISION','Le bon jugement. Au bon moment.','Les agents vous passent la main avec le contexte, les preuves et une recommandation.')}
 <div class="stat-grid decision-stats"><div class="stat-card"><span class="stat-label">À arbitrer</span><strong class="stat-value">${pending.length}</strong><span class="stat-foot">Décisions sous votre responsabilité</span></div><div class="stat-card"><span class="stat-label">Priorité haute</span><strong class="stat-value">${pending.filter(d=>d.priority==='high').length}</strong><span class="stat-foot">À examiner en premier</span></div><div class="stat-card"><span class="stat-label">Décisions traitées</span><strong class="stat-value">${s.decisions.length-pending.length}</strong><span class="stat-foot">Avec une trace dans le journal</span></div></div>
 <div class="filter-bar">${filterBtn('À traiter','pending',decisionFilter,'gov-decision-filter',pending.length)}${filterBtn('Traitées','handled',decisionFilter,'gov-decision-filter',s.decisions.length-pending.length)}${filterBtn('Toutes','all',decisionFilter,'gov-decision-filter')}</div>
 <div class="stack decision-list">${filtered.map(d=>{
  const agent=s.agents.find(a=>a.id===d.agentId), process=s.processes.find(p=>p.id===d.processId);
  return `<article class="card decision-card"><div class="decision-card-main"><div class="decision-icon ${d.priority==='high'?'priority-high':''}">${icon(d.type==='budget'?'sliders':d.type==='exception'?'alert':'inbox',21)}</div><div class="decision-copy"><div class="row decision-meta">${badge(types[d.type]||'Validation','purple')}${d.status==='pending'?badge(d.priority==='high'?'Priorité haute':'À examiner',d.priority==='high'?'amber':'neutral'):badge(d.status==='approved'?'Approuvée':'Refusée',d.status==='approved'?'green':'red')}<span class="muted small">${date(d.createdAt)}</span></div><button class="decision-title-button" data-action="gov-decision-detail" data-id="${esc(d.id)}"><h2 class="card-title">${esc(d.title)}</h2></button><p class="muted small">${esc(d.summary)}</p><div class="decision-source">${agent?avatar(agent):icon('bot',18)}<span>${esc(agent?.name||'Agent')} <span class="muted">· ${esc(process?.name||'Décision manuelle')}</span></span></div></div></div><button class="btn ${d.status==='pending'?'btn-primary':'btn-ghost'} btn-sm" data-action="gov-decision-detail" data-id="${esc(d.id)}">${d.status==='pending'?'Examiner':'Voir la décision'} ${icon('arrow',15)}</button></article>`;
 }).join('')||empty('Tout est à jour','Aucune décision dans cette vue. Vous pouvez lancer un processus pour explorer le circuit de validation.')}</div>`;
}

function decisionDrawer(d,s,ctx) {
 const agent=s.agents.find(a=>a.id===d.agentId), goal=s.goals.find(g=>g.id===d.goalId), process=s.processes.find(p=>p.id===d.processId);
 ctx.drawer({title:d.title,subtitle:`${types[d.type]||'Validation'} · ${agent?.name||'Agent'}`,body:`<div class="row between">${badge(d.status==='pending'?'Votre décision est attendue':d.status==='approved'?'Approuvée':'Refusée',d.status==='pending'?'amber':d.status==='approved'?'green':'red')}<span class="muted small">${d.dueAt?`Échéance ${date(d.dueAt)}`:''}</span></div><p class="detail-lead">${esc(d.summary)}</p><div class="detail-grid"><div class="detail-item"><span class="muted small">Agent responsable</span><strong>${esc(agent?.name||'—')}</strong></div><div class="detail-item"><span class="muted small">Processus</span><strong>${esc(process?.name||'—')}</strong></div>${d.amount?`<div class="detail-item"><span class="muted small">Montant concerné</span><strong>${money(d.amount)}</strong></div>`:''}<div class="detail-item"><span class="muted small">Responsable humain</span><strong>${esc(d.assignedTo||agent?.manager||'Matthieu')}</strong></div></div><h3 class="section-title">Éléments à votre disposition</h3>${evidence(d.evidence)}<div class="recommendation"><div class="row">${icon('bot',19)}<strong>Recommandation de l’agent</strong></div><p>${esc(d.recommendation)}</p></div>${goal?`<h3 class="section-title">Objectif concerné</h3><button class="linked-row" data-action="gov-goal-detail" data-id="${esc(goal.id)}">${icon('target',18)}<span>${esc(goal.title)}</span>${icon('arrow',16)}</button>`:''}${d.status!=='pending'?`<div class="notice"><div><strong>Décision enregistrée</strong><p>${esc(d.comment||'Sans commentaire complémentaire.')}</p></div></div>`:`<div class="drawer-actionbar"><button class="btn btn-primary" data-action="gov-review-decision" data-id="${esc(d.id)}" data-value="approved">${icon('check',16)} Approuver</button><button class="btn" data-action="gov-review-decision" data-id="${esc(d.id)}" data-value="rejected">${icon('x',16)} Refuser</button><button class="btn btn-ghost" data-action="gov-reassign-decision" data-id="${esc(d.id)}">Réaffecter</button></div><p class="form-help">Votre décision est liée à cette demande et enregistrée dans le journal.</p>`}`});
}

export function renderGaps(s) {
 const open=s.gaps.filter(g=>g.status==='open');
 const filtered=s.gaps.filter(g=>gapFilter==='dismissed'?g.status==='dismissed':gapFilter==='resolved'?g.status==='resolved':g.status==='open'&&(gapFilter==='all'||g.category===gapFilter)).sort((a,b)=>(a.impact==='high'?-1:1)-(b.impact==='high'?-1:1));
 return `${head('DIAGNOSTIC DE L’ORGANISATION','Ce qui freine vos objectifs.','Identifiez la cause, examinez les preuves et choisissez comment débloquer le travail.')}
 <div class="notice gap-notice">${icon('alert',23)}<div><strong>${open.length} points de blocage ouverts.</strong> <span class="muted">Les actions proposées sont des pistes à arbitrer. Leur impact est estimé.</span></div></div>
 <div class="filter-bar wrap-filters">${filterBtn('Tous','all',gapFilter,'gov-gap-filter',open.length)}${Object.entries(categories).map(([key,label])=>filterBtn(label,key,gapFilter,'gov-gap-filter')).join('')}${filterBtn('Plans engagés','resolved',gapFilter,'gov-gap-filter',s.gaps.filter(g=>g.status==='resolved').length)}${filterBtn('Écartés','dismissed',gapFilter,'gov-gap-filter',s.gaps.filter(g=>g.status==='dismissed').length)}</div>
 <div class="stack">${filtered.map((g,i)=>{
  const goal=s.goals.find(x=>x.id===g.goalId);
  return `<details class="card gap-card" ${i===0?'open':''}><summary class="gap-summary"><div class="icon-box ${g.impact==='high'?'amber':'purple'}">${icon(g.category==='authority'?'shield':g.category==='data'?'plug':g.category==='capacity'?'users':g.category==='capability'?'bot':'activity',21)}</div><div class="gap-summary-copy"><div class="row"><h2 class="card-title">${esc(g.title)}</h2>${g.status==='dismissed'?badge('Écarté','neutral'):g.status==='resolved'?badge(g.actionStatus==='completed'?'Action réalisée':'Plan engagé','green'):badge(g.impact==='high'?'Impact élevé':'À arbitrer',g.impact==='high'?'amber':'neutral')}</div><span class="muted small">${categories[g.category]||esc(g.category)} · ${esc(g.team)}</span></div><span class="details-chevron">${icon('chevron',18)}</span></summary><div class="gap-content"><p>${esc(g.summary)}</p>${goal?`<div class="gap-goal"><span class="muted small">Objectif concerné</span><button data-action="gov-goal-detail" data-id="${esc(goal.id)}" class="text-link">${esc(goal.title)} ${icon('arrow',13)}</button></div>`:''}${evidence(g.evidence)}<div class="row">${g.processId?`<button class="btn btn-ghost btn-sm" data-action="wf-open" data-id="${esc(g.processId)}">Voir dans le processus</button>`:''}${g.workerId?`<button class="btn btn-ghost btn-sm" data-action="gp-person" data-id="${esc(g.workerId)}">Voir le responsable du travail</button>`:''}</div><h3 class="section-title">${g.status==='resolved'?'Action retenue':'Vos options'}</h3><div class="stack">${(g.options||[]).filter(o=>g.status!=='resolved'||!g.resolvedOption||o.id===g.resolvedOption).map(o=>`<div class="option-row"><div class="option-icon">${icon(o.action==='train'?'bot':o.action==='connect'?'plug':o.action==='reassign'?'users':'check',18)}</div><div><strong>${esc(o.label)}</strong><p class="small muted">${esc(o.description)}</p><span class="option-impact">${esc(o.impact)}</span><div class="gp-gap-action-details"><span>${esc(o.leadTime||'Délai à confirmer')}</span><span>${Number(o.cost)>0?money(o.cost):'Budget à confirmer'}</span></div></div>${g.status==='open'?`<button class="btn btn-sm" data-action="gov-gap-action" data-id="${esc(g.id)}" data-option="${esc(o.id)}">Choisir ${icon('arrow',14)}</button>`:badge('Retenue','green')}</div>`).join('')}</div><div class="gp-gap-state">${g.status==='open'?`<button class="btn btn-ghost btn-sm" data-action="gov-gap-option-form" data-id="${esc(g.id)}">${icon('plus',13)} Ajouter une option</button><button class="btn btn-ghost btn-sm" data-action="gov-gap-dismiss" data-id="${esc(g.id)}">Écarter ce point</button>`:`<button class="btn btn-ghost btn-sm" data-action="gov-gap-reopen" data-id="${esc(g.id)}">Rouvrir</button>${g.status==='resolved'&&g.actionStatus!=='completed'?`<button class="btn btn-sm" data-action="gov-gap-complete" data-id="${esc(g.id)}">Documenter l’action réalisée</button>`:''}`}</div>${g.decisionNote||g.completionEvidence?`<p class="form-help">${esc(g.completionEvidence||g.decisionNote)}</p>`:''}</div></details>`;
 }).join('')||empty('Aucun point de blocage','Les problèmes correspondant à cette catégorie apparaîtront ici.')}</div>`;
}

const policyChecks={'identity':'Identité et responsable','approved-tools':'Source autorisée','external-approval':'Communication externe','budget':'Plafond budgétaire','mandate':'Mandat valide','audit':'Traçabilité'};
const policyCategories=['Données','Budget','Communication externe','Sécurité','Juridique','Autonomie','Autorité'];
export function evaluateTypedPolicy(p,input){if(!p.enabled)return {outcome:'inactive',reason:'La règle est inactive.'};if(!p.check)return {outcome:'declarative',reason:'Aucun contrôle typé : cette règle ne peut pas être évaluée automatiquement.'};const violated=({'identity':!input.registered||!input.owner,'approved-tools':!input.approvedSource,'external-approval':input.external,'budget':Number(input.amount)>Number(input.limit),'mandate':!input.validMandate,'audit':true})[p.check];if(!violated)return {outcome:'allow',reason:'Le scénario respecte cette règle.'};return {outcome:p.mode==='block'?'blocked':p.mode==='ask'?'approval':'logged',reason:({block:'L’action simulée est bloquée.',ask:'Une décision humaine est nécessaire.',log:'L’action simulée continue avec une trace.'})[p.mode]};}
function policyCoverage(p,s){const scoped=s.agents.filter(a=>p.scope.includes('Tous')||p.scope.includes('Toute')||p.scope==='Organisation'||p.scope===a.team),actors=scoped.filter(a=>p.applies!=='agent'||a.type==='agent'),processes=s.processes.filter(pr=>pr.agentIds.some(id=>actors.some(a=>a.id===id)));return {people:actors.filter(a=>a.type==='human').length,agents:actors.filter(a=>a.type==='agent').length,processes:processes.length};}
export function renderPolicies(s){const filtered=s.policies.filter(p=>policyFilter==='all'||p.category===policyFilter);return `${head('CADRE COMMUN','Des limites explicites, appliquées au travail.','Chaque règle définit son propriétaire, son périmètre et ce qui doit être bloqué, validé ou tracé.',`<button class="btn btn-primary" data-action="gov-new-policy">${icon('plus',16)} Nouvelle règle</button>`)}<div class="notice">${icon('shield',22)}<div><strong>${s.policies.filter(p=>p.enabled&&p.check).length} contrôles typés actifs.</strong> <span class="muted">Les règles déclaratives restent inactives tant que leur contrôle n’est pas défini.</span></div></div><div class="filter-bar">${filterBtn('Toutes','all',policyFilter,'gov-policy-filter')}${policyCategories.map(c=>filterBtn(c,c,policyFilter,'gov-policy-filter')).join('')}</div><div class="grid-2 policies-grid">${filtered.map(p=>{const coverage=policyCoverage(p,s),events=s.governancePlus?.security.events.filter(e=>e.policyId===p.id)||[];return `<article class="card policy-item"><div class="policy-header"><span class="eyebrow">${esc(p.id)} · ${esc(p.category)}</span>${badge(p.enabled?'Active':'Inactive',p.enabled?'green':'neutral')}</div><h2 class="card-title">${esc(p.title)}</h2><p class="muted small policy-rule">${esc(p.rule)}</p>${!p.check?'<p class="declarative-label">Règle déclarative · contrôle à définir</p>':`<div class="gp-policy-check">Contrôle : ${policyChecks[p.check]||esc(p.check)}</div>`}<div class="tag-list"><span class="tag">${icon(p.mode==='block'?'lock':p.mode==='ask'?'user':'history',13)} ${modes[p.mode]||esc(p.mode)}</span><span class="tag">${p.applies==='agent'?'Agents uniquement':'Personnes et agents'}</span><span class="tag">${esc(p.scope)}</span></div><p class="gp-security-counts">${coverage.processes} processus · ${coverage.agents} agents · ${coverage.people} personnes<br>${events.filter(e=>e.kind==='broken').length} événement(s) de violation · ${events.filter(e=>e.kind==='escalation').length} escalade(s) du scénario</p><div class="policy-footer"><span class="muted small">${esc(p.owner)}</span><button class="btn btn-ghost btn-sm" data-action="gov-policy-detail" data-id="${esc(p.id)}">Examiner ${icon('arrow',14)}</button></div></article>`;}).join('')||empty('Aucune règle','Ajoutez une règle ou choisissez une autre catégorie.')}</div>`;}
function policyForm(p,ctx){const s=ctx.getState(),isNew=!p,initial=p||{title:'',category:'Autorité',scope:'Toute l’organisation',rule:'',mode:'ask',owner:'Matthieu Keip',enabled:false,check:'',applies:'all'};ctx.closeDrawer();ctx.modal({title:isNew?'Définir une règle':'Modifier la règle',subtitle:'Le contrôle typé détermine ce que le simulateur peut vérifier.',submitLabel:isNew?'Créer la règle':'Enregistrer',body:`<div class="field"><label for="policy-title">Nom</label><input id="policy-title" name="title" value="${esc(initial.title)}" required maxlength="140"></div><div class="field"><label for="policy-rule">Règle exprimée en langage métier</label><textarea id="policy-rule" name="rule" required rows="3" maxlength="1000">${esc(initial.rule)}</textarea></div><div class="form-grid"><div class="field"><label for="policy-category">Catégorie</label><select id="policy-category" name="category">${opts(policyCategories,initial.category)}</select></div><div class="field"><label for="policy-mode">Traitement</label><select id="policy-mode" name="mode">${Object.entries(modes).map(([k,v])=>`<option value="${k}" ${k===initial.mode?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="policy-owner">Responsable</label><select id="policy-owner" name="owner">${opts([...new Set([initial.owner,...s.agents.filter(a=>a.type==='human').map(a=>a.name)])],initial.owner)}</select></div><div class="field"><label for="policy-scope">Périmètre</label><select id="policy-scope" name="scope">${opts([...new Set([initial.scope,'Toute l’organisation',...s.agents.map(a=>a.team)])],initial.scope)}</select></div><div class="field"><label for="policy-applies">Population</label><select id="policy-applies" name="applies"><option value="all" ${initial.applies!=='agent'?'selected':''}>Personnes et agents</option><option value="agent" ${initial.applies==='agent'?'selected':''}>Agents uniquement</option></select></div><div class="field"><label for="policy-check">Contrôle exécutable en simulation</label><select id="policy-check" name="check"><option value="">Aucun · règle déclarative</option>${Object.entries(policyChecks).map(([k,v])=>`<option value="${k}" ${k===initial.check?'selected':''}>${v}</option>`).join('')}</select></div></div><p class="form-help">Modifier le texte ne crée pas un nouveau contrôle. Une règle sans contrôle typé est enregistrée inactive. Testez les cas autorisés et bloqués avant activation.</p>`,onSubmit:fd=>{const check=String(fd.get('check')||''),record={...initial,id:p?.id||id('policy'),title:String(fd.get('title')||'').trim(),rule:String(fd.get('rule')||'').trim(),category:String(fd.get('category')),mode:String(fd.get('mode')),owner:String(fd.get('owner')),scope:String(fd.get('scope')),applies:String(fd.get('applies')),check,enabled:!!check&&initial.enabled};if(!record.title||!record.rule)return false;ctx.update(st=>{if(isNew)st.policies.unshift(record);else Object.assign(st.policies.find(x=>x.id===p.id),record);},isNew?'Règle créée':'Règle modifiée',record.title);ctx.toast('La règle est enregistrée.');}});}
function policyDrawer(p,ctx){const s=ctx.getState(),coverage=policyCoverage(p,s),events=s.governancePlus?.security.events.filter(e=>e.policyId===p.id)||[];ctx.drawer({title:p.title,subtitle:`${p.id} · ${p.category}`,body:`<div class="row">${badge(p.enabled?'Active':'Inactive',p.enabled?'green':'neutral')}${badge(modes[p.mode],'purple')}</div><p class="detail-lead">${esc(p.rule)}</p><div class="detail-grid"><div class="detail-item"><span>Responsable</span><strong>${esc(p.owner)}</strong></div><div class="detail-item"><span>Périmètre</span><strong>${esc(p.scope)}</strong></div><div class="detail-item"><span>Population</span><strong>${p.applies==='agent'?'Agents uniquement':'Personnes et agents'}</strong></div><div class="detail-item"><span>Couverture du scénario</span><strong>${coverage.processes} processus, ${coverage.agents} agents, ${coverage.people} personnes</strong></div></div><div class="gp-policy-evaluation"><h4>${p.check?`Contrôle typé : ${policyChecks[p.check]}`:'Règle déclarative'}</h4><p>${p.check?'Vous pouvez vérifier son comportement sur un scénario local avant de l’appliquer.':'Cette règle exprime une intention ; elle ne peut pas être activée tant que son contrôle n’est pas défini.'}</p></div><h3>Événements liés</h3>${events.map(e=>`<button class="linked-row" data-action="gp-security-event" data-id="${esc(e.id)}">${icon(e.kind==='broken'?'alert':'user',16)}<span>${esc(e.title)}</span>${icon('arrow',14)}</button>`).join('')||'<p class="muted small">Aucun événement dans le scénario.</p>'}<div class="drawer-actionbar"><button class="btn btn-primary" data-action="gov-edit-policy" data-id="${esc(p.id)}">Modifier</button>${p.check?`<button class="btn" data-action="gov-test-policy" data-id="${esc(p.id)}">Tester un scénario</button><button class="btn btn-ghost" data-action="gov-toggle-policy" data-id="${esc(p.id)}">${p.enabled?'Désactiver':'Activer'}</button>`:''}</div>`});}
function policyTest(p,ctx){ctx.closeDrawer();ctx.modal({title:'Tester le contrôle',subtitle:p.title,submitLabel:'Évaluer le scénario',body:`<div class="notice"><p>Test local sans action externe. La règle est évaluée comme active pour vérifier son comportement.</p></div><fieldset class="gp-permission-fieldset"><legend>Conditions de l’action proposée</legend>${[['registered','Agent enregistré',true],['owner','Responsable humain identifié',true],['approvedSource','Source approuvée',true],['validMandate','Mandat valide',true],['external','Communication externe',false]].map(([name,label,checked])=>`<label><input type="checkbox" name="${name}" ${checked?'checked':''}><span>${label}</span></label>`).join('')}</fieldset><div class="form-grid"><div class="field"><label for="policy-test-amount">Montant proposé (€)</label><input id="policy-test-amount" name="amount" type="number" min="0" max="10000000" value="120" required></div><div class="field"><label for="policy-test-limit">Plafond (€)</label><input id="policy-test-limit" name="limit" type="number" min="0" max="10000000" value="100" required></div></div>`,onSubmit:fd=>{const input=Object.fromEntries(['registered','owner','approvedSource','validMandate','external'].map(k=>[k,fd.has(k)]));input.amount=Number(fd.get('amount'));input.limit=Number(fd.get('limit'));const result=evaluateTypedPolicy({...p,enabled:true},input);ctx.update(st=>{st.governancePlus.policyTests||=[];st.governancePlus.policyTests.unshift({id:id('ptest'),policyId:p.id,input,result,time:new Date().toISOString()});},'Contrôle testé en simulation',`${p.title} · ${result.outcome}`);ctx.drawer({title:'Résultat du test',subtitle:p.title,body:`${badge(({allow:'Autorisé',blocked:'Bloqué',approval:'Validation humaine',logged:'Journalisé',inactive:'Inactif',declarative:'Déclaratif'})[result.outcome],result.outcome==='blocked'?'red':result.outcome==='approval'?'amber':'green')}<p class="detail-lead">${esc(result.reason)}</p><p class="form-help">Le résultat correspond uniquement aux conditions saisies et au contrôle typé sélectionné.</p><div class="drawer-actionbar"><button class="btn" data-action="gov-policy-detail" data-id="${esc(p.id)}">Retour à la règle</button></div>`});}});}

export function handleGovernance(action,el,ctx) {
 if(!action.startsWith('gov-'))return false;
 const s=ctx.getState(), recordId=el.dataset.id;
 if(action==='gov-goal-filter'){goalFilter=el.dataset.value;ctx.render();return true;}
 if(action==='gov-decision-filter'){decisionFilter=el.dataset.value;ctx.render();return true;}
 if(action==='gov-gap-filter'){gapFilter=el.dataset.value;ctx.render();return true;}
 if(action==='gov-policy-filter'){policyFilter=el.dataset.value;ctx.render();return true;}
 if(action==='gov-new-goal'){goalForm(null,s,ctx);return true;}
 if(action==='gov-new-subgoal'){goalForm(null,s,ctx,recordId);return true;}
 if(action==='gov-add-kr'||action==='gov-edit-kr'){const g=s.goals.find(x=>x.id===recordId),k=g?.krs.find(x=>x.id===el.dataset.kr);if(g)krForm(g,action==='gov-edit-kr'?k:null,ctx);return true;}
 if(action==='gov-delete-kr'){const g=s.goals.find(x=>x.id===recordId),k=g?.krs.find(x=>x.id===el.dataset.kr);if(!g||!k)return true;if(g.krs.length<2){ctx.toast('Conservez au moins un résultat clé pour cet objectif.');return true;}ctx.closeDrawer();ctx.modal({title:'Retirer ce résultat clé',subtitle:k.label,body:'<p>La progression globale sera recalculée sur les résultats restants.</p>',submitLabel:'Retirer',onSubmit:()=>{ctx.update(st=>{const goal=st.goals.find(x=>x.id===g.id);goal.krs=goal.krs.filter(x=>x.id!==k.id);goal.progress=goalMetrics(goal).progress;},'Résultat clé retiré',k.label);ctx.toast('Le résultat clé a été retiré.');}});return true;}
 if(action==='gov-edit-goal'){const g=s.goals.find(x=>x.id===recordId);if(g)goalForm(g,s,ctx);return true;}
 if(action==='gov-goal-detail'){const g=s.goals.find(x=>x.id===recordId);if(g)goalDrawer(g,s,ctx);return true;}
 if(action==='gov-process-link'){ctx.closeDrawer();ctx.navigate('processes');handleOrganization('org-process',{dataset:{id:recordId}},ctx);return true;}
 if(action==='gov-decision-detail'){const d=s.decisions.find(x=>x.id===recordId);if(d)decisionDrawer(d,s,ctx);return true;}
 if(action==='gov-review-decision'){
  const d=s.decisions.find(x=>x.id===recordId);if(!d||d.status!=='pending'){ctx.toast('Cette décision a déjà été traitée.');return true;}
  const approved=el.dataset.value==='approved';
  ctx.closeDrawer();ctx.modal({title:approved?'Approuver cette demande':'Refuser cette demande',subtitle:d.title,submitLabel:approved?'Confirmer l’approbation':'Confirmer le refus',body:`<div class="notice"><div><strong>${approved?'L’exécution concernée pourra reprendre.':'L’action proposée ne sera pas exécutée.'}</strong><p class="small muted">${esc(d.summary)}</p></div></div><div class="field"><label for="decision-comment">${approved?'Commentaire ou conditions':'Motif du refus'}</label><textarea id="decision-comment" name="comment" rows="4" ${approved?'':'required'} maxlength="1200" placeholder="${approved?'Précisez ce qui a guidé votre décision…':'Expliquez le changement attendu…'}"></textarea></div><p class="form-help">La décision et votre commentaire seront conservés dans le journal d’activité.</p>`,onSubmit:data=>{
   const comment=String(data.get('comment')||'').trim();if(!approved&&!comment){ctx.toast('Ajoutez le motif du refus.');return false;}
   try{const result=ctx.decide(d.id,approved?'approved':'rejected',comment);if(result?.ok===false){ctx.toast(result.error||'Impossible de traiter cette décision.');return false;}ctx.toast(approved?'Demande approuvée. Le processus a été mis à jour.':'Demande refusée et décision enregistrée.');}catch(error){ctx.toast(error.message||'Impossible de traiter cette décision.');return false;}
  }});return true;
 }
 if(action==='gov-reassign-decision'){
  const d=s.decisions.find(x=>x.id===recordId);if(!d)return true;
  ctx.closeDrawer();ctx.modal({title:'Réaffecter la décision',subtitle:d.title,submitLabel:'Réaffecter',body:`<div class="field"><label for="decision-owner">Responsable</label><select id="decision-owner" name="owner">${opts([...new Set(['Matthieu',...s.agents.filter(a=>a.type==='human').map(a=>a.name)])],d.assignedTo||'Matthieu')}</select></div><div class="field"><label for="decision-note">Contexte transmis</label><textarea id="decision-note" name="note" rows="3" placeholder="Pourquoi cette décision lui revient-elle ?" required maxlength="800"></textarea></div>`,onSubmit:data=>{const note=String(data.get('note')||'').trim();if(!note){ctx.toast('Ajoutez le contexte de la réaffectation.');return false;}ctx.update(st=>{const target=st.decisions.find(x=>x.id===d.id);target.assignedTo=String(data.get('owner'));target.evidence.push(`Réaffectation : ${note}`);},'Décision réaffectée',`${d.title} → ${data.get('owner')}`);ctx.toast('La décision a été réaffectée.');}});return true;
 }
 if(action==='gov-gap-dismiss'||action==='gov-gap-complete'){const gap=s.gaps.find(x=>x.id===recordId);if(!gap)return true;const complete=action==='gov-gap-complete';ctx.modal({title:complete?'Documenter l’action réalisée':'Écarter le point de blocage',subtitle:gap.title,body:`<div class="field"><label for="gap-reason">${complete?'Preuve de réalisation et suivi de l’effet':'Motif'}</label><textarea id="gap-reason" name="reason" required rows="4" maxlength="1500"></textarea></div><p class="form-help">${complete?'La réalisation de l’action ne garantit pas encore le bénéfice estimé.':'Vous pourrez rouvrir ce point si de nouveaux éléments apparaissent.'}</p>`,submitLabel:'Enregistrer',onSubmit:fd=>{const reason=String(fd.get('reason')||'').trim();if(!reason)return false;ctx.update(st=>{const g=st.gaps.find(x=>x.id===recordId);if(complete){g.actionStatus='completed';g.completionEvidence=reason;}else{g.status='dismissed';g.decisionNote=reason;}},complete?'Action documentée':'Point de blocage écarté',reason);ctx.toast('Le suivi est enregistré.');}});return true;}
 if(action==='gov-gap-reopen'){ctx.update(st=>{const g=st.gaps.find(x=>x.id===recordId);g.status='open';g.actionStatus='reopened';},'Point de blocage rouvert',recordId);ctx.toast('Le point de blocage est rouvert.');return true;}
 if(action==='gov-gap-option-form'){const gap=s.gaps.find(x=>x.id===recordId);if(!gap)return true;ctx.modal({title:'Proposer une action',subtitle:gap.title,body:`<div class="field"><label for="gap-option-label">Action</label><input id="gap-option-label" name="label" required maxlength="140"></div><div class="field"><label for="gap-option-kind">Type d’arbitrage</label><select id="gap-option-kind" name="kind"><option value="apply">Appliquer un changement</option><option value="train">Former</option><option value="hire">Recruter un agent</option><option value="open-role">Ouvrir un poste</option><option value="reassign">Réaffecter</option><option value="grant">Réviser une délégation</option><option value="connect">Connecter une source</option></select></div><div class="field"><label for="gap-option-description">Plan proposé</label><textarea id="gap-option-description" name="description" rows="3" required maxlength="800"></textarea></div><div class="form-grid"><div class="field"><label for="gap-option-delay">Délai attendu</label><input id="gap-option-delay" name="delay" required placeholder="Ex. 2 semaines"></div><div class="field"><label for="gap-option-cost">Coût estimé (€)</label><input id="gap-option-cost" name="cost" type="number" min="0" max="10000000" value="0" required></div></div><div class="field"><label for="gap-option-impact">Effet attendu, à mesurer</label><input id="gap-option-impact" name="impact" required maxlength="200"></div>`,submitLabel:'Ajouter l’option',onSubmit:fd=>{const label=String(fd.get('label')||'').trim();if(!label)return false;ctx.update(st=>st.gaps.find(x=>x.id===recordId).options.push({id:id('option'),label,description:String(fd.get('description')||'').trim(),leadTime:String(fd.get('delay')||'').trim(),cost:Number(fd.get('cost')),impact:String(fd.get('impact')||'').trim(),action:'plan-'+String(fd.get('kind'))}),'Option d’arbitrage ajoutée',label);ctx.toast('L’option est disponible.');}});return true;}
 if(action==='gov-gap-action'){
  const gap=s.gaps.find(x=>x.id===recordId), option=gap?.options.find(x=>x.id===el.dataset.option);if(!gap||!option)return true;
  ctx.modal({title:'Confirmer votre arbitrage',subtitle:gap.title,submitLabel:'Retenir cette action',body:`<div class="notice"><div><strong>${esc(option.label)}</strong><p>${esc(option.description)}</p></div></div><div class="field"><label for="gap-note">Note de décision</label><textarea id="gap-note" name="note" rows="3" maxlength="800" placeholder="Précisez le suivi attendu (facultatif)…"></textarea></div><p class="form-help">Impact estimé : ${esc(option.impact)}. Le plan d’action sera enregistré. Son effet sur les résultats restera à mesurer.</p>`,onSubmit:data=>{try{const result=option.action.startsWith('plan-')?ctx.update(st=>{const g=st.gaps.find(x=>x.id===gap.id);g.status='resolved';g.resolvedOption=option.id;g.actionStatus='planned';st.governancePlus.actionPlans||=[];st.governancePlus.actionPlans.push({id:id('plan'),gapId:g.id,optionId:option.id,type:option.action.slice(5),title:option.label,status:'planned',owner:s.agents.find(a=>a.id===g.workerId)?.manager||'Matthieu Keip',expectedImpact:option.impact,leadTime:option.leadTime,budget:option.cost,createdAt:new Date().toISOString()});},'Plan d’action créé',option.label):ctx.resolveGap(gap.id,option.id);if(result?.ok===false){ctx.toast(result.error||'Impossible de retenir cette action.');return false;}const note=String(data.get('note')||'').trim();if(note)ctx.update(st=>{st.gaps.find(x=>x.id===gap.id).decisionNote=note;},'Arbitrage documenté',note);ctx.toast('Votre arbitrage est enregistré.');}catch(error){ctx.toast(error.message||'Impossible de retenir cette action.');return false;}}});return true;
 }
 if(action==='gov-new-policy'){policyForm(null,ctx);return true;}
 if(action==='gov-test-policy'){const p=s.policies.find(x=>x.id===recordId);if(p)policyTest(p,ctx);return true;}
 if(action==='gov-policy-detail'){const p=s.policies.find(x=>x.id===recordId);if(p)policyDrawer(p,ctx);return true;}
 if(action==='gov-edit-policy'){const p=s.policies.find(x=>x.id===recordId);if(p)policyForm(p,ctx);return true;}
 if(action==='gov-toggle-policy'){
  const p=s.policies.find(x=>x.id===recordId);if(!p)return true;if(!p.check&&!p.enabled){ctx.toast('Définissez un contrôle typé avant d’activer cette règle.');return true;}
  ctx.closeDrawer();ctx.modal({title:p.enabled?'Désactiver cette règle':'Activer cette règle',subtitle:p.title,submitLabel:p.enabled?'Désactiver':'Activer',body:`<p>${p.enabled?'Cette règle ne sera plus considérée comme active dans le cadre de gouvernance de cette démonstration.':'Cette règle sera réintégrée au cadre de gouvernance actif de cette démonstration.'}</p><div class="field"><label for="policy-reason">Motif</label><textarea id="policy-reason" name="reason" required rows="3" maxlength="700" placeholder="Documentez la raison de ce changement…"></textarea></div>`,onSubmit:data=>{const reason=String(data.get('reason')||'').trim();if(!reason){ctx.toast('Documentez le motif de ce changement.');return false;}ctx.update(st=>{const current=st.policies.find(x=>x.id===p.id);current.enabled=!current.enabled;},p.enabled?'Règle désactivée':'Règle activée',`${p.title} — ${reason}`);ctx.toast('Le statut de la règle est mis à jour.');}});return true;
 }
 return false;
}
